CREATE TABLE IF NOT EXISTS "BusinessInvitation" (
 "id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL DEFAULT '',"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"acceptedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"businessId" TEXT REFERENCES "Business"("id") ON DELETE CASCADE,"sentAt" TIMESTAMP(3),"attemptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
